constexpr int kThreads = 256;
constexpr int kMaxSplits = 64;
constexpr int64_t kTargetBlocks = 1024;
__device__ __forceinline__ float ldcs1(const float* p) { return __ldcs(p); }
__device__ __forceinline__ float4 ldcs4(const float4* p) { return __ldcs(p); }
__device__ __forceinline__ void stcs1(float* p, float v) { __stcs(p, v); }
__device__ __forceinline__ void stcs4(float4* p, float4 v) { __stcs(p, v); }
__device__ __forceinline__ float ldg1(const float* p) { return __ldg(p); }
__device__ __forceinline__ float4 ldg4(const float4* p) { return __ldg(p); }
__device__ __forceinline__ void accum4(float4 v, float shift, double& s, double& q) {
  float d0 = v.x - shift;
  float d1 = v.y - shift;
  float d2 = v.z - shift;
  float d3 = v.w - shift;
  s += (double)((d0 + d1) + (d2 + d3));
  q += (double)fmaf(d0, d0, fmaf(d1, d1, fmaf(d2, d2, d3 * d3)));
}
__device__ __forceinline__ float4 norm4(float4 xv, float4 wv, float4 bv,
                                        float shift, float mean_d, float rstd) {
  float4 o;
  o.x = fmaf(((xv.x - shift) - mean_d) * rstd, wv.x, bv.x);
  o.y = fmaf(((xv.y - shift) - mean_d) * rstd, wv.y, bv.y);
  o.z = fmaf(((xv.z - shift) - mean_d) * rstd, wv.z, bv.z);
